//frame.SetEvent("onwinstat", OnWinStat);
scwin.vScrenID = "ULDSTF41303.xml";
scwin.iTimer = 0;
scwin.maxval = 0;
scwin.gOldWidthSize = frame.width;
scwin.gNewWidthSize = 0;
scwin.isCtrl = false;
scwin.pJobTitl = js_jobtitl;

