function OnSized(winID){
	if( iTimer > 0 ) window.clearInterval(iTimer);
	iTimer = 0;
	gNewWidthSize = frame.width;
	GauceObjResize(frame.width,frame.height);
}

function OnSizedMax(winID){
	if( iTimer > 0 ) window.clearInterval(iTimer);
	iTimer = 0;
	maxval = 0;
	GauceObjResize(frame.Provider("/").width,frame.height);
}

function OnWinStat(winID, statmsg){
  	if(statmsg=="activate" && winID.substring(0,6) == "Child_"){frame.Provider("/").WinActive(winID,statmsg);}

	if( statmsg == "maximize" ){
		maxval = 1;
	}else if( statmsg == "size" ){
		if(maxval == 0){
			var strFnc = "OnSized('" + winID + "')";
	  		if(iTimer > 0){
	  			window.clearInterval(iTimer);
	  			iTimer = 0;
	  		}
	  		iTimer = window.setInterval(strFnc, 300);

			}else if(maxval == 1){
			OnSizedMax(winID);
			gOldWidthSize = frame.Provider("/").width-10;
		}
  	}
 }

 function GauceObjResize(a,b){
	// 그리드메인
	var gw = (a-parseInt(grd_List.style.width)-30);
	grd_List.ReDraw = "false";
	grd_List.style.width = parseInt(grd_List.style.width) + gw;
	grd_List.ReDraw = "true";
	gOldWidthSize = frame.width;

	// 탭패널
	var pnl_main_grp = document.all("__GROUPBOX_BACKGROUND__"+"panel_Top");
	pnl_main_grp.style.width = parseInt(pnl_main_grp.style.width.replace("px","")) + gw; // 상단패널
	panel_Top.style.width = parseInt(panel_Top.style.width.replace("px","")) + gw;
	// 조회버튼
	btn_Search.style.left = parseInt(btn_Search.style.left.replace("px","")) + gw;	
	// 저장버튼
	btn_Close.style.left = parseInt(btn_Close.style.left.replace("px","")) + gw;
	btn_Excel.style.left = parseInt(btn_Excel.style.left.replace("px","")) + gw;

}
// grid resize 종료부
*/

scwin.fr_SecuGrpId = SECUGRP_ID_EW;
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};
scwin.fn_RefreshForm = function(interval) {
    setInterval("fn_list_sync();", interval);
};
scwin.fn_GetParIsuCd = function(arrPar) {
    // 넘길 인수를 지정하는 펑션
    arrPar[0] = ""; // 코드값을 포함할 컨트롤
    arrPar[1] = ""; // 명칭값을 포함할 컨트롤
    arrPar[2] = scwin.fr_SecuGrpId;
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************
    arrPar, length;
};
scwin.fn_SetParIsuCd = function(arrPar) {
    txb_ISU_CD.setValue(arrPar[0].ISU_CD);
    txb_ISU_NM.setValue(arrPar[0].ISU_KOR_NM);
};
scwin.fn_clslog_sync = function() {
    var url;
    url = "/ELWEaryEnd.do?method=listElwKoSetlRptLog&inputMessageId=ELW_KO_SETL_RPT_CLS_OUT";
    url += "&TASK_DD=" + $c.stf.getObjectValue(edt_SDate);
    dts_ClsLog.DataID = encodeURI(url);
    dts_ClsLog.reset();
};


// 담당자 승인, 팀장승인, 재마감처리 
scwin.buttonSetDis = function() {
    var vCurDate = $c.ut.cGetToday("yyyymmdd");
    if (vCurDate != edt_SDate.getValue()) {
        btn_Revw.src = "../img/btn/btn_revw_d.gif";
        btn_Revw.setDisabled(true);
        btn_Cls.src = "../img/btn_BosApv_d.gif";
        btn_Cls.setDisabled(true);
        return true;
    }

    //담당자일때
    if (scwin.pJobTitl == "03") {
        if ($c.stf.getObjectValue(txb_BZ_CLS_TM) != "") // 담당자가 이미 확인처리한 경우

        {
            btn_Revw.src = "../img/btn/btn_revw_d.gif";
            btn_Revw.setDisabled(true);
            btn_Cls.src = "../img/btn_BosApv_d.gif";
            btn_Cls.setDisabled(true);
        } else if ($c.stf.getObjectValue(txb_TEAMLEADR_APPROV_TM) != "") {
            btn_Revw.src = "../img/btn/btn_revw_d.gif";
            btn_Revw.setDisabled(true);
            btn_Cls.src = "../img/btn_BosApv_d.gif";
            btn_Cls.setDisabled(true);
        } else {
            btn_Revw.src = "../img/btn/btn_revw.gif";
            btn_Revw.setDisabled(false);
            btn_Cls.src = "../img/btn_BosApv_d.gif";
            btn_Cls.setDisabled(true);
        }
    }
    //팀장일때 - 마감처리
    else {
        // 당번 아이디 들어온 경우 담당자,팀장 확인 처리할수 함
        if ($c.stf.getObjectValue(txb_BZ_CLS_TM) == "" && $c.stf.getObjectValue(txb_TEAMLEADR_APPROV_TM) == "") {
            btn_Revw.src = "../img/btn/btn_revw.gif";
            btn_Revw.setDisabled(false);
            btn_Cls.src = "../img/btn_BosApv_d.gif";
            btn_Cls.setDisabled(true);
        } else if ($c.stf.getObjectValue(txb_TEAMLEADR_APPROV_TM) != "") {
            btn_Revw.src = "../img/btn/btn_revw_d.gif";
            btn_Revw.setDisabled(true);
            btn_Cls.src = "../img/btn_BosApv_d.gif";
            btn_Cls.setDisabled(true);
        } else {
            btn_Revw.src = "../img/btn/btn_revw_d.gif";
            btn_Revw.setDisabled(true);
            btn_Cls.src = "../img/btn_BosApv.gif";
            btn_Cls.setDisabled(false);
        }
    }
};
scwin.fn_list_sync = function() {
    scwin.fn_clslog_sync();
    if (MaxTab_01.getSelectedTabIndex() == 1) {
        //			edt_SDate.text = cGetToday("yyyymmdd");		// 현재날짜

        $c.stf.showObj(edt_EDate, false);
        $c.stf.showObj(img_EDate, false);
        $c.stf.showObj(cmb_PeriodTp, false);
        $c.stf.showObj(label_4, false);
        edt_SDate.setDisabled(false);
        img_SDate.setDisabled(false);
        $c.stf.showObj(txb_CHRG_EMP_NM, true);
        $c.stf.showObj(txb_BZ_CLS_TM, true);
        $c.stf.showObj(txb_APPROV_TEAMLEADR_EMP_NM, true);
        $c.stf.showObj(txb_TEAMLEADR_APPROV_TM, true);
        $c.stf.showObj(label_9, true);
        $c.stf.showObj(label_8, true);
        $c.stf.showObj(label_7, true);
        $c.stf.showObj(label_6, true);
        var url = "/ELWEaryEnd.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=listElwKoSetlRpt&inputMessageId=ELW_KO_SETL_RPT_OUT";
        url += "&OCCR_DD=" + $c.stf.getObjectValue(cmb_DateType); //발생일
        url += "&SDATE_O=" + $c.stf.getObjectValue(edt_SDate);
        url += "&EDATE_O=" + $c.stf.getObjectValue(edt_SDate);
        url += "&REPORT_DD=" + $c.stf.getObjectValue(cmb_DateType); //제출일
        url += "&SDATE_R=" + $c.stf.getObjectValue(edt_SDate);
        url += "&EDATE_R=" + $c.stf.getObjectValue(edt_SDate);


        //alert(getObjectValue(edt_SDate)+"//"+getObjectValue(edt_EDate)+"//"+getObjectValue(txb_ISU_CD));
        dts_List.DataID = encodeURI(url);
        dts_List.reset();
        $c.cm.ShowWin(grd_List_1);
    } else if (MaxTab_01.getSelectedTabIndex() == 2) {
        $c.stf.showObj(edt_EDate, true);
        $c.stf.showObj(img_EDate, true);
        $c.stf.showObj(cmb_PeriodTp, true);
        $c.stf.showObj(label_4, true);
        edt_SDate.setDisabled(false);
        img_SDate.setDisabled(false);
        $c.stf.showObj(txb_CHRG_EMP_NM, false);
        $c.stf.showObj(txb_BZ_CLS_TM, false);
        $c.stf.showObj(txb_APPROV_TEAMLEADR_EMP_NM, false);
        $c.stf.showObj(txb_TEAMLEADR_APPROV_TM, false);
        $c.stf.showObj(label_9, false);
        $c.stf.showObj(label_8, false);
        $c.stf.showObj(label_7, false);
        $c.stf.showObj(label_6, false);
        var url = "/ELWEaryEnd.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=listElwKoSetlRpt&inputMessageId=ELW_KO_SETL_RPT_OUT";
        url += "&OCCR_DD=" + $c.stf.getObjectValue(cmb_DateType); //발생일
        url += "&SDATE_O=" + $c.stf.getObjectValue(edt_SDate);
        url += "&EDATE_O=" + $c.stf.getObjectValue(edt_EDate);
        url += "&REPORT_DD=" + $c.stf.getObjectValue(cmb_DateType); //제출일
        url += "&SDATE_R=" + $c.stf.getObjectValue(edt_SDate);
        url += "&EDATE_R=" + $c.stf.getObjectValue(edt_EDate);

        //alert(getObjectValue(edt_SDate)+"//"+getObjectValue(edt_EDate)+"//"+getObjectValue(txb_ISU_CD));
        dts_List_2.DataID = encodeURI(url);
        dts_List_2.reset();
        $c.cm.ShowWin(grd_List_2);
    }
    scwin.buttonSetDis();
};
scwin.fn_save = function() {
    var res = window.confirm("확인 저장 하겠습니까?");
    //alert(js_id+"//"+dts_List.NameString(dts_List.RowPosition,'ISU_CD')+"//"+dts_List.NameString(dts_List.RowPosition,'OCCR_DD')+"//"+dts_List.NameString(dts_List.RowPosition,'OCCR_TM'));
    if (res) {
        var url = "/ELWEaryEnd.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_02 + "&method=saveELWEaryEnd";
        url += "&USR_ID=" + js_id;
        url += "&ISU_CD=" + dts_List.getCellData(dts_List.getRowPosition(), 'ISU_CD');
        url += "&OCCR_DD=" + dts_List.getCellData(dts_List.getRowPosition(), 'OCCR_DD');
        url += "&OCCR_TM=" + dts_List.getCellData(dts_List.getRowPosition(), 'OCCR_TM');
        dts_parameter.DataID = encodeURI(url);
        dts_parameter.reset();
        scwin.fn_list_sync();
    }
};



//담당자 확인 버튼 클릭시
scwin.fn_revw = function() {
    if ($c.stf.getObjectValue(txb_BZ_CLS_TM) != "") {
        $c.win.alert("담당자가 이미 확인하였습니다.");
        return true;
    }
    var res = window.confirm("담당자 확인 저장하시겠습니까?");
    if (res) {
        var url = "/ELWEaryEnd.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_02 + "&method=saveELWKoSetlRptCls";
        url += "&USR_ID=" + js_id;
        url += "&TEAMLEADER_YN=" + "N";
        dts_parameter.DataID = encodeURI(url);
        dts_parameter.reset();
        scwin.fn_list_sync();
    }
};



//2010.03.09 팀장승인 버튼 클릭시
scwin.fn_cls = function() {
    if ($c.stf.getObjectValue(txb_CHRG_EMP_NM) == "") {
        $c.win.alert("담당자가 확인하지 않았습니다. 담당자 확인 후 마감처리를 해주십시오.");
        return true;
    }
    var commit = window.confirm("마감처리 하시겠습니까?");
    if (commit) {
        var url = "/ELWEaryEnd.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_02 + "&method=saveELWKoSetlRptCls";
        url += "&USR_ID=" + js_id;
        url += "&TEAMLEADER_YN=" + "Y";
        dts_parameter.DataID = encodeURI(url);
        dts_parameter.reset();
        scwin.fn_list_sync();
    }
};



//담당자 확인
scwin.fn_trs_revw = function() {
    fn_trSetHeader();
    dts_Cls.setCellData(1, "CHRG_EMP_NO", js_emp_no);
    trs_revw.Action = "/ELWLPHolding.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=revwProcsSave";
    trs_revw.KeyName = "toinb_dataid4";
    trs_revw.KeyValue = "JSP(I:pInput=dts_Cls)";
    trs_revw.Post();
};





//팀장승인 
scwin.fn_trs = function() {
    fn_trSetHeader();
    dts_Cls.setCellData(1, "CHRG_EMP_NO", js_emp_no);
    trs_Cls.Action = "/ELWLPHolding.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=clsProcsSave";
    trs_Cls.KeyName = "toinb_dataid4";
    trs_Cls.KeyValue = "JSP(I:pInput=dts_Cls)";
    trs_Cls.Post();
};
scwin.btn_Search_onclick = function() {
    scwin.fn_list_sync();
};
scwin.dts_List_OnLoadError = function() {
    $c.stf.alert_error(dts_List);
};
scwin.dts_List_OnLoadCompleted = function(rowcount) {
    $c.stf.FillGridHeaderTotalCnt(rowcount, panel_page);
    $c.cm.CloseWin(rowcount, grd_List_1);
    scwin.buttonSetDis();
};
scwin.dts_List_2_OnLoadCompleted = function(rowcount) {
    $c.stf.FillGridHeaderTotalCnt(rowcount, panel_page);
    $c.cm.CloseWin(rowcount, grd_List_2);
};
scwin.cmb_PeriodTp_OnSelChange = function() {
    var vTp = $c.cp.valueOfIndex(cmb_PeriodTp, "VALUE", cmb_PeriodTp.getSelectedIndex());
    $c.stf.fn_setFromToDate(vTp, edt_SDate, edt_EDate);
};
scwin.img_SDate_onclick = function() {
    popUpCalendar2(edt_SDate);
};
scwin.img_EDate_onclick = function() {
    popUpCalendar2(edt_EDate);
};
scwin.btn_Close_onclick = function() {
    self.close();
};
scwin.btn_Excel_onclick = function() {
    //엑셀 로그 
    $c.stf.doLogSave(scwin.vScrenID, SCREN_PROCS_TP_CD_07);
    if (MaxTab_01.getSelectedTabIndex() == 1) {
        $c.data.downloadGridViewExcel(grd_List_1, "ELW 조기종료평가처리", "", "8");
    } else if (MaxTab_01.getSelectedTabIndex() == 2) {
        $c.data.downloadGridViewExcel(grd_List_2, "ELW 조기종료평가내역", "", "8");
    }
};
scwin.gform_onload = function() {
    $c.cm.PanelToGroupBox(panel_Top);
    var vCurDate = $c.ut.cGetToday("yyyymmdd");
    edt_SDate.setValue(vCurDate); //cGetMinusDate2(vCurDate, 1); 	// 일주일전 날짜
    edt_EDate.setValue($c.ut.cGetToday("yyyymmdd")); // 현재날짜

    scwin.fn_list_sync();
    $c.stf.Combo_CBDataSetPeriod(cmb_PeriodTp);
    scwin.fn_RefreshForm(60000);
};
scwin.grd_List_1_OnCheckClick = function(col, colid, bCheck) {
    if (bCheck != 0) {
        scwin.fn_save();
    }
};
scwin.trs_Save_OnFail = function() {
    $c.stf.alert_error(trs_Save);
};
scwin.trs_Save_OnSuccess = function() {
    scwin.fn_list_sync();
    dts_List.reset();
};
scwin.MaxTab_01_OnSelChanged = function(nIndex) {
    scwin.fn_list_sync();
};
scwin.btn_Revw_onclick = function() {
    scwin.fn_revw();
};
scwin.btn_Cls_onclick = function() {
    scwin.fn_cls();
};
